const source = $input.first().json || {};
const original = $('Determinístico — Normalizar entrada mínima').first().json || {};
const fields = source.fields || {};

function parseObject(value) {
  if (!value) return {};
  if (typeof value === 'object') return value;
  try { return JSON.parse(value); } catch (e) { return { raw: String(value) }; }
}

const messageCount = Number(fields['Cantidad Intercambios'] || fields.message_count || 0);

return [{
  json: {
    ...original,
    memory_record_id: source.id || null,
    long_term_memory: {
      exists: Boolean(source.id && fields['Session_ID']),
      session_id: fields['Session_ID'] || original.session_id,
      user_name: fields['Nombre Usuario'] || null,
      case_status: fields['Estado del Caso'] || 'nuevo',
      last_summary: fields['Resumen Consolidado'] || 'No existe resumen previo para esta sesión.',
      key_data: parseObject(fields['Datos Clave']),
      message_count: messageCount,
      last_intent: fields['Ultima Intencion'] || null,
      last_worker: fields['Ultimo Worker'] || null,
      requires_human: Boolean(fields['Requiere Humano'] || false),
      last_request_id: fields['Request_ID Ultimo'] || null
    }
  }
}];

